import{c as a,Q as t,j as o,m as r}from"./chunks/framework.BvWD_EvC.js";const i="/next/screenshots/library-read.png",p=JSON.parse('{"title":"Library","description":"","frontmatter":{},"headers":[],"relativePath":"guide/using-librislog/library.md","filePath":"guide/using-librislog/library.md","lastUpdated":1788850495000}'),s={name:"guide/using-librislog/library.md"};function n(l,e,d,c,h,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="library" tabindex="-1">Library <a class="header-anchor" href="#library" aria-label="Permalink to &quot;Library&quot;">​</a></h1><p>The library is the heart of LibrisLog. It organizes your books into four reading statuses and provides tools for managing your collection.</p><h2 id="reading-statuses" tabindex="-1">Reading Statuses <a class="header-anchor" href="#reading-statuses" aria-label="Permalink to &quot;Reading Statuses&quot;">​</a></h2><p>Books are categorized into four statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>Description</th></tr></thead><tbody><tr><td><strong>Want to Read</strong></td><td>Books you plan to read</td></tr><tr><td><strong>Currently Reading</strong></td><td>Books you&#39;re actively reading</td></tr><tr><td><strong>Read</strong></td><td>Books you&#39;ve finished</td></tr><tr><td><strong>Did Not Finish</strong></td><td>Books you started but abandoned</td></tr></tbody></table><p>Each status has its own tab in the library view, making it easy to browse your collection by reading state. A fifth <strong>All Books</strong> tab shows every book regardless of status; like the other tabs it supports search and sorting (smart sort is disabled there, since it&#39;s based on per-status defaults).</p><h2 id="possession" tabindex="-1">Possession <a class="header-anchor" href="#possession" aria-label="Permalink to &quot;Possession&quot;">​</a></h2><p>Possession is separate from reading status. Choose whether a book is owned, borrowed, available digitally, or still needs to be acquired. In the Want to Read view, books that still need to be acquired show a shopping-cart indicator. Use the possession filter to narrow the list without changing its newest-first order.</p><p><img src="'+i+'" alt="Library" loading="lazy"></p><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><ul><li>Switch between tabs using the bottom navigation bar on mobile or the sidebar on desktop</li><li>Books are displayed as cards with cover images, titles, and authors</li><li>Click any book to open the detail view</li></ul><h2 id="book-cards" tabindex="-1">Book Cards <a class="header-anchor" href="#book-cards" aria-label="Permalink to &quot;Book Cards&quot;">​</a></h2><p>Each book card shows:</p><ul><li>Cover image (or placeholder if no cover)</li><li>Title and author</li><li>Current reading progress (for &quot;Currently Reading&quot; books)</li><li>Star rating (for &quot;Read&quot; books)</li></ul><h2 id="detail-view" tabindex="-1">Detail View <a class="header-anchor" href="#detail-view" aria-label="Permalink to &quot;Detail View&quot;">​</a></h2><p>Clicking a book opens the detail dialog/drawer showing:</p><ul><li>Full cover image</li><li>Complete metadata (title, subtitle, author, ISBN, publisher, year, pages, language)</li><li>Reading status badge</li><li>Star rating (clickable to change)</li><li>Reading progress slider (for books with page count)</li><li>Tags</li><li>Notes</li><li>Blurb/description with expand/collapse</li><li>Action buttons: Edit, Delete</li></ul><h2 id="adding-books" tabindex="-1">Adding Books <a class="header-anchor" href="#adding-books" aria-label="Permalink to &quot;Adding Books&quot;">​</a></h2><h3 id="manual-entry" tabindex="-1">Manual Entry <a class="header-anchor" href="#manual-entry" aria-label="Permalink to &quot;Manual Entry&quot;">​</a></h3><p>Use the &quot;Add Book&quot; button to manually enter book details. Fill in title, author, and optional fields like ISBN, publisher, page count, etc.</p><p>A book can have <strong>multiple authors</strong>: type a name and press <strong>Enter</strong> to add it as a chip. Authors are shown joined with &quot;; &quot; throughout the app, so names written last-name-first (e.g. <code>&quot;Doe, Jane&quot;</code>) stay unambiguous.</p><h3 id="import-search" tabindex="-1">Import Search <a class="header-anchor" href="#import-search" aria-label="Permalink to &quot;Import Search&quot;">​</a></h3><p>Search external sources for book metadata:</p><ul><li><strong>Open Library</strong> — Free, no API key required</li><li><strong>Google Books</strong> — Requires API key (set in <code>.env</code>)</li><li><strong>Hardcover.app</strong> — Requires API token (set in <code>.env</code>)</li></ul><p>Open Library and Hardcover (if an API token is configured) are queried <strong>in parallel</strong> for both title and ISBN searches. Google Books is only used as a <strong>fallback</strong> when the other sources return no results, or on demand via the <strong>Search Google Books too</strong> button, which adds Google Books results to the current results.</p><p>While a search is running, the <strong>Search</strong> button changes to <strong>Cancel</strong>, so you can stop the request at any time and refine your query.</p><h4 id="how-results-are-grouped" tabindex="-1">How results are grouped <a class="header-anchor" href="#how-results-are-grouped" aria-label="Permalink to &quot;How results are grouped&quot;">​</a></h4><p>Different providers often describe the same book slightly differently (title language, page count, publisher, cover). Instead of dropping these variants, LibrisLog keeps every result and groups the ones that represent the same book. Each group shows a <strong>&quot;N results&quot;</strong> badge with a <strong>Show editions</strong> toggle: expand it to review the individual records and pick the one you want to import.</p><p>Results are grouped by this rule:</p><ul><li><strong>Same ISBN</strong>: if two results carry the same ISBN, they are grouped together. ISBN-10 and ISBN-13 forms of the same ISBN count as equal (e.g. <code>0441013597</code> and <code>9780441013593</code>).</li><li><strong>No ISBN, same title + same authors</strong>: results without an ISBN are grouped by a normalized title (case- and whitespace-insensitive) together with the same sorted author names.</li></ul><p>Consequences you may notice:</p><ul><li>Two results with the <em>same title</em> but <strong>different ISBNs</strong> are <strong>not</strong> grouped: they are different editions (different language, publisher, or page count) and appear as separate entries.</li><li>A result with an ISBN and a result without one are never grouped, even if the title and authors match.</li><li>Results that differ only in metadata (cover, publisher, page count, description) but share an ISBN or title+author are grouped so you can compare them side by side.</li></ul><p>Because an ISBN can only be owned once per user, a group with a shared ISBN always represents a single book, so importing one variant is enough.</p><h3 id="isbn-barcode-scan" tabindex="-1">ISBN Barcode Scan <a class="header-anchor" href="#isbn-barcode-scan" aria-label="Permalink to &quot;ISBN Barcode Scan&quot;">​</a></h3><p>Use the camera to scan ISBN barcodes. The app uses the device&#39;s camera with real-time barcode detection to quickly look up books.</p><div class="warning custom-block"><p class="custom-block-title">Requires a secure context</p><p>Camera access is only available when LibrisLog is served in a <strong>secure context</strong>. A page is a secure context when it is served over <strong>HTTPS</strong> or from <code>http://localhost</code> (or <code>http://127.0.0.1</code>). Accessing the app via a plain <code>http://</code> address on a remote host — e.g. <code>http://192.168.1.10:8001</code> — is <strong>not</strong> a secure context, and the camera will not start. See <a href="https://developer.mozilla.org/en-US/docs/Web/Security/Dangerous_Contexts" target="_blank" rel="noreferrer">MDN: Secure contexts</a> for details.</p><p>If the barcode scan button is hidden or the scanner shows a black box, your browser is likely blocking camera access because the app is not running in a secure context. Serve LibrisLog behind HTTPS (a reverse proxy with a TLS certificate) or access it via <code>localhost</code> to enable scanning.</p></div><h2 id="editing-books" tabindex="-1">Editing Books <a class="header-anchor" href="#editing-books" aria-label="Permalink to &quot;Editing Books&quot;">​</a></h2><p>Click the &quot;Edit&quot; button in the detail view to modify any book property. Changes are saved immediately.</p><h2 id="covers" tabindex="-1">Covers <a class="header-anchor" href="#covers" aria-label="Permalink to &quot;Covers&quot;">​</a></h2><h3 id="automatic-cover-search" tabindex="-1">Automatic Cover Search <a class="header-anchor" href="#automatic-cover-search" aria-label="Permalink to &quot;Automatic Cover Search&quot;">​</a></h3><p>When adding a book, the app automatically searches for cover images from:</p><ul><li>AbeBooks</li><li>Open Library</li><li>Amazon</li><li>Hardcover</li></ul><h3 id="cover-picker" tabindex="-1">Cover Picker <a class="header-anchor" href="#cover-picker" aria-label="Permalink to &quot;Cover Picker&quot;">​</a></h3><p>If automatic search doesn&#39;t find a suitable cover, you can:</p><ul><li>Upload an image file</li><li>Paste an image URL</li><li>Trigger a manual cover search</li></ul><h3 id="cover-caching" tabindex="-1">Cover Caching <a class="header-anchor" href="#cover-caching" aria-label="Permalink to &quot;Cover Caching&quot;">​</a></h3><p>Downloaded covers are cached locally in the <code>COVERS_DIR</code> directory to avoid repeated external requests.</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><ul><li>Search books by title, author, or tags using the search bar — the result count updates as you type</li><li>Field-specific queries are supported, e.g. <code>author:Murakami</code>, <code>availability:owned</code>, or <code>tag:fantasy</code>. See the <a href="/next/guide/using-librislog/search.html">search syntax reference</a> for the full list of prefixes and examples.</li><li>Press <strong>Enter</strong> to open the dedicated search results page with a full results grid, load-more pagination, and the same book detail interaction as the library</li><li>From any page, navigate directly to <code>/search?q=your+query</code> for quick access</li></ul><h2 id="sort" tabindex="-1">Sort <a class="header-anchor" href="#sort" aria-label="Permalink to &quot;Sort&quot;">​</a></h2><ul><li>Sort by title, date added, date started, date finished, or rating</li><li>Sort order: ascending or descending</li></ul><h2 id="view-modes" tabindex="-1">View Modes <a class="header-anchor" href="#view-modes" aria-label="Permalink to &quot;View Modes&quot;">​</a></h2><p>Switch between grid view (cover-focused) and list view (compact) using the view toggle.</p>',53)])])}const b=a(s,[["render",n]]);export{p as __pageData,b as default};
